        },
        "text": "Design"
    },
    {
        "type": "ListItem",
        "element_id": "af14c0ecaaa7ac1d2bca5cdfbcc32ec7",
        "metadata": {
            "filename": "Bank Good Credit Loan.pptx",
            "file_directory": "tmpdocs",
