        "text": "GAGAS Performance Audits: Discussion of Concepts to Consider When Auditing Public Functions and Services"
    },
    {
        "type": "NarrativeText",
        "element_id": "6c7d2f92f64287dd9ab227ad5c8b54fc",
        "metadata": {
            "coordinates": {
                "points": [
