                    ],
                    [
                        571.8,
                        573.3
                    ]
                ],
                "system": "PixelSpace",
                "layout_width": 612.0,
                "layout_height": 792.0
            },
            "filename": "Performance-Audit-Discussion.pdf",
            "file_directory": "tmpdocs",
            "last_modified": "2023-11-02T15:16:47",
            "filetype": "application/pdf",
            "parent_id": "9bdb2a16884b7f663fb433076e0da16c",
            "page_number": 3,
            "links": []
        },
        "text": "The administration of a government program or activity is economical when it minimizes the costs of resources used in performing its functions while meeting timeliness and quality considerations for those resources. When auditing economy, auditors primarily focus on the costs of inputs rather than on the outcomes achieved."
    },
    {
        "type": "NarrativeText",
        "element_id": "0570a941ed2cc8770fef88241b5168ce",
        "metadata": {
            "coordinates": {
