                    ]
                ],
                "system": "PixelSpace",
                "layout_width": 612.0,
                "layout_height": 792.0
            },
            "filename": "Performance-Audit-Discussion.pdf",
            "file_directory": "tmpdocs",
            "last_modified": "2023-11-02T15:16:47",
            "filetype": "application/pdf",
            "parent_id": "cbfa75893f5d570acffb728e22430c72",
            "page_number": 4,
            "links": []
        },
        "text": "Example: In a performance audit assessing agency officials\u2019 compliance with conflict-of-interest requirements, auditors may compare a sample of financial disclosure reports filed against requirements in statute or regulation."
    },
