                    ],
                    [
                        252.0,
                        609.9
                    ],
                    [
                        577.1,
                        609.9
                    ],
                    [
                        577.1,
                        559.9
                    ]
                ],
                "system": "PixelSpace",
                "layout_width": 612.0,
                "layout_height": 792.0
            },
            "filename": "Performance-Audit-Discussion.pdf",
            "file_directory": "tmpdocs",
            "last_modified": "2023-11-02T15:16:47",
            "filetype": "application/pdf",
            "parent_id": "be315c294e89da2fc16a03db7ee60db5",
            "page_number": 5,
            "links": []
        },
        "text": "Example: In a performance audit assessing scholarship outcomes in higher education programs, auditors may report on the distribution of scholarships by race, gender identity, and income to illuminate potential disparities among scholarship recipients."
    },
    {
        "type": "NarrativeText",
        "element_id": "234e7ada767cf237379e4b835b80bd6a",
